CREATE TABLE professional_credentials (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, staff_identity_id BIGINT UNSIGNED NOT NULL, regulator_id BIGINT UNSIGNED NOT NULL, registration_number VARCHAR(100) NOT NULL, additional_credentials VARCHAR(500) NULL, FOREIGN KEY(staff_identity_id) REFERENCES staff_identities(id), FOREIGN KEY(regulator_id) REFERENCES master_data(id), UNIQUE(staff_identity_id,regulator_id,registration_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
